const __pageData = JSON.parse('{"title":"Agent 分层记忆体系：从认知模型到 Mem0 工程实践","description":"","frontmatter":{"title":"Agent 分层记忆体系：从认知模型到 Mem0 工程实践","date":"2026-08-04T00:00:00.000Z","category":"AI","cover":"/covers/backend.svg","tags":["ai","agent","memory","mem0","spring-ai"],"excerpt":"从工作、会话与长期记忆出发，拆解语义、情景、程序性记忆，比较主流 Agent 框架，并给出 Spring Boot 接入 Mem0 的完整工程方案。"},"headers":[],"relativePath":"posts/agent-layered-memory-mem0-engineering.md","filePath":"posts/agent-layered-memory-mem0-engineering.md","lastUpdated":1787128073000}');
